export const baseUiDialogBackdropClassName =
  "fixed inset-0 bg-black/50 transition duration-150 ease-out data-[closed]:opacity-0";

export const baseUiDialogPanelClassName =
  "mx-auto max-w-md rounded-lg bg-white p-6 shadow-xl transition duration-150 ease-out data-[closed]:scale-95 data-[closed]:opacity-0";

export const baseUiDialogTitleClassName = "text-lg font-semibold text-gray-900";

export const baseUiDialogDescriptionClassName = "mt-2 text-base text-gray-600";

import { describe, expect, test } from "vitest";

import * as Dialog from "./index";

describe("Base UI Dialog registry view", () => {
  test("reuses the Foldkit Dialog functional contract", () => {
    expect(Dialog.init).toBeTypeOf("function");
    expect(Dialog.update).toBeTypeOf("function");
    expect(Dialog.root).toBeTypeOf("function");
    expect(Dialog.baseUiDialogPanelClassName).toContain("rounded");
  });
});
